configuration.tbelDecoder:
/** Decoder **/

var data = decodeToJson(payload);

// Nel debug di ThingsBoard/Sentinel il messaggio arriva spesso come:
// {
//   "topic": "...",
//   "payload": {...}
// }
//
// Nel messaggio MQTT reale invece potrebbe arrivare direttamente:
// {
//   "device_id": "...",
//   ...
// }

var p = {};

if (data && data.payload) {
    p = data.payload;
} else if (data) {
    p = data;
}

var hw = p.hw || {};
var ram = hw.ram || {};
var disk = hw.disk || {};
var analysis = p.analysis || {};

function safeNumber(value, fallback) {
    if (value === undefined || value === null || value === "") {
        return fallback;
    }

    var n = Number(value);

    if (isNaN(n)) {
        return fallback;
    }

    return n;
}

function safeString(value, fallback) {
    if (value === undefined || value === null) {
        return fallback;
    }

    return String(value);
}

function boolToNumber(value) {
    return value === true ? 1 : 0;
}

return {
    deviceName: safeString(p.device_id, "sensore_001"),
    deviceType: "Optical Biosensor",

    attributes: {
        sample_id: safeString(p.sample_id, ""),
        image_name: safeString(p.image_name, ""),
        image_path: safeString(analysis.image_path, "")
    },

    telemetry: {
        frame_id: safeNumber(p.frame_id, 0),

        detected: boolToNumber(analysis.detected),
        spore_count: safeNumber(analysis.spore_count, 0),

        growth_stage: safeString(analysis.growth_stage, ""),
        growth_stage_raw: safeString(analysis.growth_stage_raw, ""),
        risk_level: safeString(analysis.risk_level, ""),
        stage_confirmed: boolToNumber(analysis.stage_confirmed),

        development_index: safeNumber(analysis.development_index, 0),
        tracked_spore_count: safeNumber(analysis.tracked_spore_count, 0),
        cumulative_germination_percent: safeNumber(analysis.cumulative_germination_percent, 0),
        avg_time_to_germination_s: safeNumber(analysis.avg_time_to_germination_s, 0),
        avg_elongation_rate_um_per_min: safeNumber(analysis.avg_elongation_rate_um_per_min, 0),

        cpu_temp_c: safeNumber(hw.cpu_temp_c, 0),
        processing_time_s: safeNumber(hw.processing_time_s, 0),

        ram_used_mb: safeNumber(ram.used_mb, 0),
        ram_total_mb: safeNumber(ram.total_mb, 0),
        ram_used_percent: safeNumber(ram.used_percent, 0),

        disk_used_mb: safeNumber(disk.used_mb, 0),
        disk_free_mb: safeNumber(disk.free_mb, 0),
        disk_used_percent: safeNumber(disk.used_percent, 0)
    }
};
